package com.nook.phone;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.hardware.biometrics.BiometricPrompt;import android.net.Uri;import android.provider.Settings;import android.view.*;import android.widget.*;import android.text.InputFilter;import org.json.*;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;

public final class MainActivity extends Activity {
    private final ExecutorService network=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());private NookApi api;private LinearLayout root,content;private TextView status,chatReply;private EditText draft;private Spinner providers;private boolean visible,busy;private JSONObject state=new JSONObject();private CancellationSignal biometric;
    private final Runnable refresh=new Runnable(){public void run(){if(visible&&api.paired()&&!busy)load();if(visible)handler.postDelayed(this,4000);}};
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    private TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextColor(Color.rgb(237,240,246));v.setTextSize(size);v.setPadding(0,dp(5),0,dp(5));return v;}
    private LinearLayout card(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);v.setPadding(dp(20),dp(16),dp(20),dp(16));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.rgb(20,20,25));bg.setCornerRadius(dp(26));v.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(10),0,dp(6));v.setLayoutParams(p);return v;}
    private Button button(String label,Runnable action){Button v=new Button(this);v.setText(label);v.setAllCaps(false);v.setTextColor(Color.rgb(237,240,246));v.setOnClickListener(view->action.run());return v;}
    private void job(Callable<JSONObject> work,java.util.function.Consumer<JSONObject> done){if(busy)return;busy=true;network.execute(()->{try{JSONObject result=work.call();handler.post(()->{if(!isDestroyed()){busy=false;done.accept(result);}});}catch(Exception e){handler.post(()->{busy=false;if(!isDestroyed()){if(!api.paired()){stopService(new Intent(this,IslandService.class));pairing();}status.setText(e.getMessage()==null?"Could not reach the PC. Check Wi-Fi and pairing.":e.getMessage());}});}});}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);api=new NookApi(this);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(22),dp(34),dp(22),dp(30));scroll.addView(root);setContentView(scroll);root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets safe=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(dp(22),safe.top+dp(12),dp(22),safe.bottom+dp(18));return insets;});PetView pet=new PetView(this);root.addView(pet,new LinearLayout.LayoutParams(dp(80),dp(80)));root.addView(text("Nook",30));status=text("Your workspace, in your pocket.",13);root.addView(status);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);root.addView(content);if(api.paired())dashboard();else pairing();handleLink(getIntent());}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleLink(intent);}
    private void handleLink(Intent intent){Uri data=intent.getData();if(data!=null&&"nook".equals(data.getScheme())&&"pair".equals(data.getHost()))confirmPair(data.toString());}
    private void pairing(){content.removeAllViews();LinearLayout panel=card();panel.addView(text("Pair with your PC",20));panel.addView(text("Open Connection health & studio on your PC and show the Android pairing QR. Scan with your phone camera or paste the link below.",14));EditText link=new EditText(this);link.setSingleLine();link.setHint("nook://pair?…");link.setTextColor(Color.WHITE);link.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2000)});panel.addView(link);panel.addView(button("Review pairing",()->confirmPair(link.getText().toString())));content.addView(panel);}
    private void confirmPair(String link){try{Uri u=Uri.parse(link);String url=u.getQueryParameter("url"),pin=u.getQueryParameter("pin");if(url==null||pin==null)throw new Exception();NookApi.validate(url,pin);new AlertDialog.Builder(this).setTitle("Pair this computer?").setMessage(url+"\n\nCertificate: "+pin.substring(0,12)+"…\n\nUse the link displayed by your own Nook PC. Access can be revoked there.").setNegativeButton("Cancel",null).setPositiveButton("Pair",(d,w)->job(()->{api.pair(link);return new JSONObject();},r->{status.setText("Paired securely over local Wi-Fi.");dashboard();load();})).show();}catch(Exception e){status.setText("Paste a complete HTTPS Nook pairing link from your PC.");}}
    private void dashboard(){content.removeAllViews();LinearLayout tools=card();tools.addView(button("Refresh agents",this::load));tools.addView(button("Enable activity island",()->{if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));status.setText("Allow Nook to display over other apps, then tap Enable again.");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},1);startForegroundService(new Intent(this,IslandService.class));status.setText("Activity island enabled. Stop it from its notification.");}));tools.addView(button("Stop activity island",()->stopService(new Intent(this,IslandService.class))));tools.addView(button("Disconnect phone",()->{stopService(new Intent(this,IslandService.class));network.execute(()->{try{api.request("/logout","POST",new JSONObject());}catch(Exception ignored){}api.clear();handler.post(()->{NookWidget.update(this,"Disconnected");pairing();});});}));content.addView(tools);}
    private void load(){job(()->api.request("/state","GET",null),result->{state=result;status.setText(result.optString("status","Connected"));NookWidget.updateState(this,result);if(draft==null||!draft.hasFocus())render();});}
    private void render(){String savedDraft=draft==null?"":draft.getText().toString(),savedReply=chatReply==null?"":chatReply.getText().toString(),savedProvider=providers==null||providers.getSelectedItem()==null?"":providers.getSelectedItem().toString();dashboard();JSONObject pending=state.optJSONObject("pending");if(pending!=null){LinearLayout request=card();request.addView(text("Needs your attention",20));request.addView(text(pending.optString("agent")+" · "+pending.optString("title"),15));request.addView(button("Review request",()->review(pending)));content.addView(request);}JSONArray sessions=state.optJSONArray("sessions");if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject session=sessions.optJSONObject(i);if(session==null)continue;LinearLayout item=card();item.addView(text(session.optString("label",session.optString("agent")),18));item.addView(text(session.optBoolean("finished")?"Finished":session.optString("task","Working"),13));if(state.optBoolean("detailsEnabled"))item.addView(button("View session",()->job(()->api.request("/session?id="+URLEncoder.encode(session.optString("id"),StandardCharsets.UTF_8.name()),"GET",null),this::showSession)));content.addView(item);}
      if(state.optBoolean("chatEnabled")){LinearLayout chat=card();chat.addView(text("Chat with your AI",20));providers=new Spinner(this);JSONArray list=state.optJSONArray("chatProviders");java.util.ArrayList<String> names=new java.util.ArrayList<>();if(list!=null)for(int i=0;i<list.length();i++)names.add(list.optJSONObject(i).optString("id"));providers.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));if(names.contains(savedProvider))providers.setSelection(names.indexOf(savedProvider));chat.addView(providers);chatReply=text(savedReply,14);chatReply.setTextIsSelectable(true);chat.addView(chatReply);draft=new EditText(this);draft.setTextColor(Color.WHITE);draft.setHint("Ask something…");draft.setText(savedDraft);draft.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2000)});chat.addView(draft);chat.addView(button("Send",()->{String message=draft.getText().toString().trim();if(message.isEmpty()||providers.getSelectedItem()==null||busy)return;String p=providers.getSelectedItem().toString();draft.setText("");chatReply.setText("Thinking…");job(()->api.request("/chat","POST",new JSONObject().put("provider",p).put("text",message)),r->chatReply.setText(r.optString("reply")));}));chat.addView(text("Uses your PC’s API keys. Provider charges may apply. PC chat history and attachments are not shared.",12));content.addView(chat);}
    }
    private void showSession(JSONObject data){LinearLayout view=new LinearLayout(this);view.setOrientation(LinearLayout.VERTICAL);view.setPadding(dp(20),dp(12),dp(20),dp(12));view.addView(text(data.optString("agent")+" · "+(data.optBoolean("finished")?"Finished":"Working"),14));JSONArray steps=data.optJSONArray("steps");if(steps!=null)for(int i=0;i<steps.length();i++){JSONObject step=steps.optJSONObject(i);if(step==null)continue;view.addView(text(step.optString("title",step.optString("task")),16));view.addView(text(step.optString("file")+" · +"+step.optInt("added")+" −"+step.optInt("removed"),12));if(!step.optString("diff").isEmpty()){TextView diff=text(step.optString("diff"),12);diff.setTypeface(android.graphics.Typeface.MONOSPACE);diff.setTextIsSelectable(true);view.addView(diff);}}if(!data.optString("final").isEmpty()){view.addView(text("Agent reply",18));TextView answer=text(data.optString("final"),14);answer.setTextIsSelectable(true);view.addView(answer);}ScrollView scroll=new ScrollView(this);scroll.addView(view);new AlertDialog.Builder(this).setTitle(data.optString("label","Session")).setView(scroll).setPositiveButton("Close",null).show();}
    private void review(JSONObject request){String id=request.optString("id");LinearLayout view=new LinearLayout(this);view.setPadding(dp(20),dp(8),dp(20),dp(8));view.setOrientation(LinearLayout.VERTICAL);view.addView(text(request.optString("detail"),14));JSONObject answers=new JSONObject();JSONArray questions=request.optJSONArray("questions");java.util.ArrayList<Runnable> readers=new java.util.ArrayList<>();if(questions!=null)for(int i=0;i<questions.length();i++){JSONObject q=questions.optJSONObject(i);if(q==null)continue;view.addView(text(q.optString("question"),15));JSONArray choices=q.optJSONArray("options");if(choices!=null&&choices.length()>0){java.util.ArrayList<CheckBox> checks=new java.util.ArrayList<>();for(int j=0;j<choices.length();j++){JSONObject option=choices.optJSONObject(j);String label=option==null?choices.optString(j):option.optString("label");CheckBox check=new CheckBox(this);check.setText(label);check.setTextColor(Color.WHITE);checks.add(check);view.addView(check);if(!q.optBoolean("multiSelect"))check.setOnCheckedChangeListener((v,on)->{if(on)for(CheckBox other:checks)if(other!=v)other.setChecked(false);});}readers.add(()->{java.util.ArrayList<String> picked=new java.util.ArrayList<>();for(CheckBox check:checks)if(check.isChecked())picked.add(check.getText().toString());try{answers.put(q.optString("question"),String.join(", ",picked));}catch(JSONException ignored){}});}else{EditText answer=new EditText(this);answer.setTextColor(Color.WHITE);answer.setFilters(new InputFilter[]{new InputFilter.LengthFilter(4000)});view.addView(answer);readers.add(()->{try{answers.put(q.optString("question"),answer.getText().toString().trim());}catch(JSONException ignored){}});}}
      ScrollView scroll=new ScrollView(this);scroll.addView(view);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(request.optString("title","Review request")).setView(scroll).setNegativeButton("Deny",(d,w)->decide(id,"deny",answers)).setNeutralButton("Cancel",null).setPositiveButton("Allow",null).create();dialog.setOnShowListener(d->{Button allow=dialog.getButton(AlertDialog.BUTTON_POSITIVE);allow.setEnabled(false);handler.postDelayed(()->allow.setEnabled(true),600);allow.setOnClickListener(v->{for(Runnable reader:readers)reader.run();for(java.util.Iterator<String> it=answers.keys();it.hasNext();)if(answers.optString(it.next()).isEmpty()){status.setText("Answer every question before allowing.");return;}biometric=new CancellationSignal();new BiometricPrompt.Builder(this).setTitle("Allow this Nook request?").setSubtitle("Confirm the request you reviewed").setAllowedAuthenticators(android.hardware.biometrics.BiometricManager.Authenticators.BIOMETRIC_STRONG|android.hardware.biometrics.BiometricManager.Authenticators.DEVICE_CREDENTIAL).build().authenticate(biometric,getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){dialog.dismiss();decide(id,"allow",answers);}@Override public void onAuthenticationError(int code,CharSequence message){status.setText(message);}});});});dialog.show();
    }
    private void decide(String id,String action,JSONObject answers){job(()->api.request("/decide","POST",new JSONObject().put("id",id).put("action",action).put("answers",answers)),r->{status.setText(action.equals("allow")?"Request allowed":"Request denied");load();});}
    @Override protected void onStart(){super.onStart();visible=true;handler.post(refresh);}
    @Override protected void onStop(){super.onStop();visible=false;handler.removeCallbacks(refresh);if(biometric!=null)biometric.cancel();}
    @Override protected void onDestroy(){super.onDestroy();handler.removeCallbacksAndMessages(null);network.shutdownNow();}
}
